Rebot HTML<pre><code>&lt;div class="box bounce"&gt;Rebot&lt;/div&gt;

&lt;style&gt;
  .box {
    width: 120px;
    height: 120px;
    background: #ffffff;
    border-radius: 10px;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 14px;
    font-weight: bold;
    color: #333;
    text-align: center;
    border: 3px solid #333; /* Borde de la caixa */
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2); /* Ombra per fer que sembli una caixa */
    transition: all 0.3s ease; /* Transició suau en l'animació */
  }

  @keyframes bounce {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-50px); }
  }

  .bounce {
    animation: bounce 2s infinite;
  }
&lt;/style&gt;
</code></pre>

Rotació HTML<pre><code>&lt;div class="box rotate"&gt;Rotació&lt;/div&gt;

&lt;style&gt;
  @keyframes rotate {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }

  .rotate {
    animation: rotate 3s infinite linear;
  }
&lt;/style&gt;
</code></pre>

Pulsació HTML<pre><code>&lt;div class="box pulse"&gt;Pulsació&lt;/div&gt;

&lt;style&gt;
  @keyframes pulse {
    0%, 100% { transform: scale(1); }
